#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES — 접속기록 반출(S3)을 켜는 AWS 마법사 (G-23 ⑩, ADR 0105)
#
#     bash scripts/aws-wizard.sh
#
# 원본은 `docs/ops/runbook/security.md` 「반출 — 매일 S3」이고, 이 마법사는 그 절의 걸음을 차례 그대로 밟는다 —
# **Governance 1일로 시험 → 검증 → Compliance 400일 전환.** 인증은 Vercel OIDC → IAM 역할(단기 자격)만 만든다.
# 접근 키(대안)는 runbook 의 「대안」을 손으로 밟는다.
#
# - **몇 번 돌려도 된다.** 걸음마다 AWS 의 지금 상태를 먼저 읽고, 있으면 그대로 쓰고 모자란 것만 더한다 —
#   버킷 · OIDC 제공자 · 역할은 두 번 만들어지지 않는다. 중간에 멈추면(Ctrl-C · 오류) 다시 돌리면 이어진다.
# - **값은 저장소 밖에 둔다** — `~/.config/saju/aws-wizard.env`(`AWS_WIZARD_STATE` 로 바꾼다). 버킷 이름 · 역할 ARN ·
#   계정 번호 · 걸음의 날짜뿐이고 비밀은 없다(열쇠를 만들지 않는다). 그래도 문서 · 채팅 · 커밋에 옮기지 않는다.
# - **되돌릴 수 없는 걸음은 묻는다** — Compliance 전환은 버킷 이름을 그대로 쳐야 간다.
# - **검증은 그 검증이 본 설정에만 유효하다** — 지문(버킷 · 역할 · 정책 · Vercel 팀 · 프로젝트)이 달라졌거나 Redeploy ·
#   Vercel 세 값의 확인이 남았으면 Stage 12 를 다시 잰다. Compliance 가 400일보다 짧으면 끝냈다고 하지 않는다.
# - 시험: `scripts/aws-wizard.test.ts` — 가짜 `aws` · `vercel` · `npm` 으로 처음 · 재실행 · 부분 실패 · 재사용 · 전환을 잰다.
# ──────────────────────────────────────────────────────────────────────────

# bash 4.4 이상이어야 한다 — 아래 `inherit_errexit` 와 연관 배열(`declare -A`)이 그 판부터다. macOS 의 `/bin/bash` 는
# 3.2 라 `shopt` 에서 알 수 없는 이름으로 죽는다 — 그 전에 까닭과 까는 길을 말하고 멈춘다
if (( BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 4) )); then
  printf '이 마법사는 bash 4.4 이상에서 돈다 — 지금은 %s 다. macOS 면 `brew install bash` 뒤 새 터미널에서 `bash scripts/aws-wizard.sh`\n' "$BASH_VERSION" >&2
  exit 1
fi

# 명령 치환 안의 실패도 멈추게 한다 — 없으면 `x=$(실패하는 함수)` 가 조용히 지나간다. 함수 안의 실패도
# 오류 알림(on_error)을 거치게 한다(-E)
shopt -s inherit_errexit
set -E

TOTAL_STAGES=13

ENV_FILE="${AWS_WIZARD_STATE:-$HOME/.config/saju/aws-wizard.env}"
mkdir -p "$(dirname "$ENV_FILE")"

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

# 코드가 기대하는 이름 — 바꾸면 코드와 runbook 도 함께(`app/api/cron/audit-export/export.ts` 의 `configOf` · `s3.ts`)
REGION="ap-northeast-2"
ADMIN_PROFILE="saju-admin"
VERIFY_PROFILE="saju-audit-verify"
EXPORT_ROLE="saju-audit-export"
VERIFY_ROLE="saju-audit-verify"
EXPORT_PREFIX="operator-access"
# 지우기 시험 객체의 자리 — 반출(쓰기 역할)도 검증(읽기 역할)도 닿지 않는다
PROBE_PREFIX="wizard-probe"
CRON_PATH="/api/cron/audit-export"
BUCKET_STEM="saju-audit-"
# Compliance 의 목표 일수 — 이보다 짧으면 끝나지 않았다
COMPLIANCE_DAYS=400

# 이번 실행에서 남은 것 — 끝에 한꺼번에 보인다
REMAINING=()

# ── 도우미 ────────────────────────────────────────────────────────────────

# 관리자 프로필로 부른다 — 루트 자격은 CLI 에서 쓰지 않는다
awsa() { aws --profile "$ADMIN_PROFILE" --region "$REGION" "$@"; }

# 상태 파일의 값 하나 (없으면 빈 문자열)
state() { _existing "$1" || true; }

# 상태 파일에 적는다 — 화면에는 이름만 찍힌다
remember() { write_env "$1" "$2"; }

today() { date +%F; }
now() { date +%s; }
# 「하루 돌려」 — 날짜 글자가 아니라 시각으로 잰다. 24시간이면 매일의 정기 반출(03:37 전후)이 그 사이에 한 번 돈다
DAY=86400

# 오류로 멈추면 어디서 멈췄는지와 다시 도는 법만 말한다
# 알림은 처음의 표준 출력(3)으로 — 실패한 명령이 `>/dev/null` 안에 있어도 보이게
exec 3>&1
on_error() {
  # 명령 치환 안에서 난 것은 바깥이 한 번 더 받는다 — 한 번만 말한다
  (( BASH_SUBSHELL == 0 )) || return 0
  {
    printf '\n'
    warn "Stage ${_STAGE_INDEX}/${TOTAL_STAGES} 에서 멈췄다(줄 $1)."
    note "다시 돌리면 이미 된 걸음은 건너뛰고 여기서 이어진다:  bash scripts/aws-wizard.sh"
    note "복구 절차: docs/ops/runbook/security.md 「마법사가 멈췄을 때」"
  } >&3
}
trap 'on_error $LINENO' ERR

# 멈춰야 하는 까닭을 말하고 끝낸다 — 오류 알림(on_error)은 겹쳐 찍지 않는다
stop() {
  trap - ERR
  warn "$1"
  [[ -z "${2:-}" ]] || note "$2"
  exit 1
}

# head-bucket 의 결과를 셋으로 — ours(이 계정이 본다) · missing(없다) · taken(남의 것이거나 못 본다)
bucket_state() {
  local err
  if err=$(awsa s3api head-bucket --bucket "$1" 2>&1 >/dev/null); then echo ours; return; fi
  if grep -qE '404|Not Found|NoSuchBucket' <<<"$err"; then echo missing; else echo taken; fi
}

# Object Lock 의 지금 기본 보존 — "MODE DAYS"(기본 보존이 없으면 "None None"), Object Lock 이 꺼졌으면 "off".
# 못 읽으면(일시 장애 · 자격) 꺼짐으로 보지 않고 실패한다 — 부르는 쪽은 `x=$(lock_state …)` 로 받아 멈춘다
lock_state() {
  local out enabled mode days
  if ! out=$(awsa s3api get-object-lock-configuration --bucket "$1" \
      --query 'ObjectLockConfiguration.[ObjectLockEnabled,Rule.DefaultRetention.Mode,Rule.DefaultRetention.Days]' \
      --output text 2>&1); then
    if grep -q 'ObjectLockConfigurationNotFoundError' <<<"$out"; then echo off; return; fi
    printf '%s\n' "$out" >&2
    return 1
  fi
  read -r enabled mode days <<<"$out"
  [[ "$enabled" == "Enabled" ]] || { echo off; return; }
  echo "${mode:-None} ${days:-None}"
}

# 역할을 만들거나(없으면) 신뢰 정책을 맞춘다(있으면). 권한 정책은 이름이 같으면 덮어쓴다 — 몇 번 돌려도 하나다.
# 표준 출력은 역할 ARN 하나뿐이다(안내는 표준 오류로)
ensure_role() {
  local name="$1" trust="$2" policy_name="$3" policy="$4" arn
  if arn=$(awsa iam get-role --role-name "$name" --query Role.Arn --output text 2>/dev/null); then
    step "역할 $name 이 이미 있다 — 다시 쓰고 신뢰 정책만 맞춘다" >&2
    awsa iam update-assume-role-policy --role-name "$name" --policy-document "$trust" >/dev/null
  else
    arn=$(awsa iam create-role --role-name "$name" --assume-role-policy-document "$trust" \
      --query Role.Arn --output text)
    step "역할 $name 을 만들었다" >&2
  fi
  awsa iam put-role-policy --role-name "$name" --policy-name "$policy_name" --policy-document "$policy" >/dev/null
  step "권한 정책 $policy_name 을 맞췄다" >&2
  printf '%s' "$arn"
}

# 검증이 본 설정의 지문 — 인자를 줄마다 이어 sha256 하나로. 상태 파일에는 지문으로만 남는다.
# macOS 에는 `sha256sum` 이 없고 `shasum -a 256` 이 있다 — 같은 값을 낸다(WSL 에서 적은 지문을 맥에서 다시 잰다)
fingerprint() {
  if command -v sha256sum >/dev/null 2>&1; then printf '%s\n' "$@" | sha256sum | cut -d' ' -f1
  else printf '%s\n' "$@" | shasum -a 256 | cut -d' ' -f1; fi
}

# Production 의 실제 값을 읽는다 — 세 이름(비밀이 아니다)만 연관 배열 remote 에 담는다.
# `vercel env pull` 은 다른 변수(비밀 포함)도 함께 쓰므로, 저장소 밖 임시 폴더(권한 700)에 받아 세 이름만 뽑고
# 곧 지운다 — 파일 내용은 화면에도 로그에도 내지 않는다. 못 읽으면 1 을 돌려준다(부르는 쪽이 「확인 못 함」으로)
declare -A remote=()
read_vercel_values() {
  local dir file line name value rc=0
  dir=$(mktemp -d "${TMPDIR:-/tmp}/saju-aws-wizard.XXXXXX") || return 1
  chmod 700 "$dir"
  file="$dir/production.env"
  if (umask 077 && vercel env pull "$file" --environment production "${vercel_scope[@]}" --yes) >/dev/null 2>&1 \
      && [[ -f "$file" ]]; then
    for name in AUDIT_EXPORT_BUCKET AUDIT_EXPORT_REGION AUDIT_EXPORT_ROLE_ARN; do
      line=$(grep -E "^${name}=" "$file" | tail -n1 || true)
      [[ -n "$line" ]] || continue
      value="${line#*=}"
      value="${value%\"}"; value="${value#\"}"
      remote[$name]="$value"
    done
  else
    rc=1
  fi
  rm -rf "$dir"
  return "$rc"
}

# ── 시작 ─────────────────────────────────────────────────────────────────

banner "AWS — 접속기록 반출(S3) 켜기"

# 처음 도는 날의 기본값 — 물을 때 Enter 로 그대로 쓴다
[[ -n "$(state VERCEL_TEAM)" ]] || remember VERCEL_TEAM "sungheeyoons-projects"
[[ -n "$(state VERCEL_PROJECT)" ]] || remember VERCEL_PROJECT "saju"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "준비물 — AWS CLI · Vercel CLI"
missing_tool=""
if ! command -v aws >/dev/null 2>&1; then
  warn "aws 가 없다 — AWS CLI v2(2.32 이상, aws login 이 든다)를 깐다"
  open_url "https://docs.aws.amazon.com/cli/latest/userguide/getting-started-install.html"
  missing_tool=1
else
  aws_ver=$(aws --version 2>&1 | sed -n 's|^aws-cli/\([0-9]*\)\.\([0-9]*\)\..*|\1 \2|p')
  read -r major minor <<<"${aws_ver:-0 0}"
  if (( major < 2 || (major == 2 && minor < 32) )); then
    warn "AWS CLI 가 2.32 보다 낮다 — aws login 이 없다. 올린 뒤 다시 돌린다"
    open_url "https://docs.aws.amazon.com/cli/latest/userguide/getting-started-install.html"
    missing_tool=1
  else
    step "AWS CLI ${major}.${minor} — 됐다"
  fi
fi
if ! command -v vercel >/dev/null 2>&1; then
  warn "vercel 이 없다 — npm i -g vercel 로 깔고 vercel login 뒤 다시 돌린다"
  missing_tool=1
elif ! vercel whoami >/dev/null 2>&1; then
  warn "Vercel 에 로그인이 안 돼 있다 — vercel login 뒤 다시 돌린다"
  missing_tool=1
else
  step "Vercel CLI — 로그인돼 있다"
fi
[[ -z "$missing_tool" ]] || stop "준비물이 모자라 여기서 멈춘다. 갖추고 다시 돌리면 이어진다."
ask VERCEL_TEAM "Vercel 팀 슬러그(팀 주소의 경로):"
ask VERCEL_PROJECT "Vercel 프로젝트 이름:"
remember VERCEL_TEAM "$VERCEL_TEAM"
remember VERCEL_PROJECT "$VERCEL_PROJECT"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "AWS 계정 · 루트 MFA"
if [[ "$(state ACCOUNT_READY)" == "yes" ]]; then
  step "지난 실행에서 끝냈다 — 건너뛴다"
else
  say "계정을 열고 루트 사용자에 MFA 를 건다(G-23 ⑨). 루트는 이 걸음과 다음 걸음의 관리자 만들기에만 쓴다."
  open_url "https://signup.aws.amazon.com/signup?request_type=register"
  step "계정을 만든다(이미 있으면 루트로 로그인만)"
  step "오른쪽 위 계정 이름 → Security credentials → Multi-factor authentication (MFA) → Assign MFA device"
  step "패스키나 OTP 앱으로 등록한다"
  pause "계정과 루트 MFA 를 끝냈으면 [Enter]"
  remember ACCOUNT_READY "yes"
fi

# ── 3 ────────────────────────────────────────────────────────────────────
stage "관리자 사용자 · CLI 로그인"
caller_arn=""
if caller_arn=$(awsa sts get-caller-identity --query Arn --output text 2>/dev/null); then
  step "프로필 $ADMIN_PROFILE 로 이미 로그인돼 있다"
else
  say "루트로 CLI 를 돌리지 않는다 — 콘솔에서 관리자 사용자 하나를 만들고 그 사용자로 로그인한다."
  open_url "https://console.aws.amazon.com/iam/home#/users/create"
  step "User name: $ADMIN_PROFILE · Provide user access to the AWS Management Console 을 켠다 · 비밀번호는 직접 정한다"
  step "Permissions: Attach policies directly → AdministratorAccess 와 SignInLocalDevelopmentAccess"
  step "만든 뒤 그 사용자 → Security credentials → Assign MFA device"
  step "루트에서 로그아웃하고 $ADMIN_PROFILE 사용자로 콘솔에 다시 들어간다"
  pause "$ADMIN_PROFILE 로 콘솔에 들어갔으면 [Enter] — 이어서 브라우저로 CLI 로그인을 연다"
  aws login --profile "$ADMIN_PROFILE" --region "$REGION"
  caller_arn=$(awsa sts get-caller-identity --query Arn --output text)
fi
[[ "$caller_arn" != *":root" ]] || stop "루트로 로그인됐다 — 루트는 역할을 맡을 수 없고, CLI 에서 쓰지 않는다." \
  "aws logout --profile $ADMIN_PROFILE 뒤 다시 돌려 $ADMIN_PROFILE 사용자로 로그인한다."
# 검증 역할(Stage 9)은 이 사용자 하나만 믿는다 — 역할 세션(SSO 등)이면 누구를 믿을지 좁힐 수 없어 멈춘다
[[ "$caller_arn" == arn:aws:iam::*:user/* ]] || stop "IAM 사용자가 아닌 신원으로 로그인됐다 — 검증 역할을 그 사람 하나로 좁힐 수 없다." \
  "aws logout --profile $ADMIN_PROFILE 뒤 다시 돌려 $ADMIN_PROFILE 사용자로 로그인한다."
account_id=$(awsa sts get-caller-identity --query Account --output text)
remember AWS_ACCOUNT_ID "$account_id"
remember AWS_ADMIN_ARN "$caller_arn"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "감사 버킷 — 서울 · Object Lock · 공개 차단"
bucket="$(state AUDIT_EXPORT_BUCKET)"
if [[ -z "$bucket" ]]; then
  # 상태 파일을 잃었어도 이미 만든 버킷을 다시 쓴다 — 두 개를 만들지 않는다
  found=$(awsa s3api list-buckets --query "Buckets[?starts_with(Name, '${BUCKET_STEM}')].Name" --output text)
  read -r -a found_list <<<"${found//None/}"
  if (( ${#found_list[@]} == 1 )); then
    bucket="${found_list[0]}"
    step "이 계정에 있던 버킷을 다시 쓴다"
  elif (( ${#found_list[@]} > 1 )); then
    warn "${BUCKET_STEM}* 버킷이 여럿이다: ${found_list[*]}"
    ask AUDIT_EXPORT_BUCKET "반출에 쓸 버킷 이름:"
    bucket="$AUDIT_EXPORT_BUCKET"
  fi
fi
[[ -n "$bucket" ]] || bucket="${BUCKET_STEM}$(od -An -N4 -tx1 /dev/urandom | tr -d ' \n')"
case "$(bucket_state "$bucket")" in
  ours)
    step "버킷 $bucket — 이미 있다, 다시 쓴다" ;;
  missing)
    # 만들기 전에 이름부터 적는다 — 만든 직후 멈춰도 다음 실행이 같은 이름을 찾는다
    remember AUDIT_EXPORT_BUCKET "$bucket"
    awsa s3api create-bucket --bucket "$bucket" \
      --create-bucket-configuration "LocationConstraint=$REGION" \
      --object-lock-enabled-for-bucket >/dev/null
    step "버킷 $bucket 을 만들었다(Object Lock 켬 — Versioning 이 함께 켜지고 끌 수 없다)" ;;
  *)
    stop "버킷 이름 $bucket 을 이 계정이 못 쓴다(남의 것이거나 권한이 없다)." \
      "상태 파일의 AUDIT_EXPORT_BUCKET 줄을 지우고 다시 돌리면 새 이름을 짓는다: $ENV_FILE" ;;
esac
remember AUDIT_EXPORT_BUCKET "$bucket"
lock=$(lock_state "$bucket")
[[ "$lock" != "off" ]] || stop "버킷 $bucket 에 Object Lock 이 꺼져 있다 — 반출 버킷으로 못 쓴다." \
  "복구: docs/ops/runbook/security.md 「마법사가 멈췄을 때」의 「Object Lock 이 꺼져 있다」"
versioning=$(awsa s3api get-bucket-versioning --bucket "$bucket" --query Status --output text)
[[ "$versioning" == "Enabled" ]] || stop "Versioning 이 $versioning 이다 — Object Lock 버킷이면 Enabled 여야 한다."
awsa s3api put-public-access-block --bucket "$bucket" --public-access-block-configuration \
  BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true >/dev/null
step "Block Public Access 넷을 켰다 · 암호화는 S3 기본(SSE-S3)"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Object Lock — Governance 1일로 시험한다"
lock=$(lock_state "$bucket")
read -r mode days <<<"$lock"
case "$mode" in
  COMPLIANCE)
    step "이미 Compliance ${days}일이다 — 건드리지 않는다" ;;
  GOVERNANCE)
    step "이미 Governance ${days}일이다 — 그대로 둔다"
    [[ -n "$(state GOVERNANCE_SET_EPOCH)" ]] || remember GOVERNANCE_SET_EPOCH "$(now)" ;;
  *)
    say "기본 보존을 Governance 1일로 둔다 — 하루 돌려 검증한 뒤(Stage 12) Compliance 로 옮긴다(Stage 13)."
    say "Governance 는 s3:BypassGovernanceRetention 으로 풀 수 있어, 잘못 올린 시험 객체를 지울 수 있다."
    if confirm "기본 보존을 Governance 1일로 걸까?"; then
      awsa s3api put-object-lock-configuration --bucket "$bucket" --object-lock-configuration \
        '{"ObjectLockEnabled":"Enabled","Rule":{"DefaultRetention":{"Mode":"GOVERNANCE","Days":1}}}' >/dev/null
      remember GOVERNANCE_SET_EPOCH "$(now)"
      step "Governance 1일을 걸었다"
    else
      REMAINING+=("Stage 5 — 기본 보존 Governance 1일이 안 걸렸다")
    fi ;;
esac

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Vercel — OIDC Federation 켜기"
if [[ "$(state VERCEL_OIDC_READY)" == "yes" ]]; then
  step "지난 실행에서 켰다 — 건너뛴다"
else
  open_url "https://vercel.com/${VERCEL_TEAM}/${VERCEL_PROJECT}/settings/security"
  step "Settings → Security → Secure backend access with OIDC federation → Enabled"
  step "Issuer Mode: Team(발급자 https://oidc.vercel.com/${VERCEL_TEAM}) → Save"
  note "메뉴 이름이 다르면 https://vercel.com/docs/oidc 를 본다"
  if confirm "OIDC Federation 을 Team 으로 켜고 저장했나?"; then
    remember VERCEL_OIDC_READY "yes"
  else
    REMAINING+=("Stage 6 — Vercel OIDC Federation(Team)")
  fi
fi

# ── 7 ────────────────────────────────────────────────────────────────────
stage "AWS — Vercel 을 믿는 OIDC 제공자"
issuer_host="oidc.vercel.com/${VERCEL_TEAM}"
audience="https://vercel.com/${VERCEL_TEAM}"
provider_arn="arn:aws:iam::${account_id}:oidc-provider/${issuer_host}"
if clients=$(awsa iam get-open-id-connect-provider --open-id-connect-provider-arn "$provider_arn" \
    --query ClientIDList --output text 2>/dev/null); then
  step "제공자가 이미 있다 — 다시 쓴다"
  if ! tr '\t' '\n' <<<"$clients" | grep -qxF "$audience"; then
    awsa iam add-client-id-to-open-id-connect-provider --open-id-connect-provider-arn "$provider_arn" \
      --client-id "$audience" >/dev/null
    step "audience 를 더했다"
  fi
else
  awsa iam create-open-id-connect-provider --url "https://${issuer_host}" --client-id-list "$audience" >/dev/null
  step "제공자를 만들었다 — https://${issuer_host}"
fi

# ── 8 ────────────────────────────────────────────────────────────────────
stage "반출 역할 — $EXPORT_ROLE (넣기 하나)"
export_trust='{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Principal":{"Federated":"'"$provider_arn"'"},"Action":"sts:AssumeRoleWithWebIdentity","Condition":{"StringEquals":{"'"$issuer_host"':aud":"'"$audience"'","'"$issuer_host"':sub":"owner:'"$VERCEL_TEAM"':project:'"$VERCEL_PROJECT"':environment:production"}}}]}'
export_policy='{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Action":"s3:PutObject","Resource":"arn:aws:s3:::'"$bucket/$EXPORT_PREFIX"'/*"}]}'
say "이 프로젝트의 Production 만 믿고, 그 버킷의 ${EXPORT_PREFIX}/ 에 넣기만 한다 — 읽기 · 지우기 · 보존 변경이 없다."
export_role_arn=$(ensure_role "$EXPORT_ROLE" "$export_trust" "${EXPORT_ROLE}-put" "$export_policy")
remember AUDIT_EXPORT_ROLE_ARN "$export_role_arn"

# ── 9 ────────────────────────────────────────────────────────────────────
stage "검증 역할 — $VERIFY_ROLE (읽기 · 사람만)"
# Stage 3 이 IAM 사용자만 들인다 — 그 사용자 하나만 믿는다
verify_principal="$caller_arn"
verify_trust='{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Principal":{"AWS":"'"$verify_principal"'"},"Action":"sts:AssumeRole"}]}'
verify_policy='{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Action":"s3:GetObject","Resource":"arn:aws:s3:::'"$bucket/$EXPORT_PREFIX"'/*"},{"Effect":"Allow","Action":"s3:ListBucket","Resource":"arn:aws:s3:::'"$bucket"'","Condition":{"StringLike":{"s3:prefix":"'"$EXPORT_PREFIX"'/*"}}}]}'
say "반출의 쓰기 역할과 따로 — Vercel 에는 넣지 않고, 이 기계의 프로필 $VERIFY_PROFILE 로만 맡는다."
verify_role_arn=$(ensure_role "$VERIFY_ROLE" "$verify_trust" "${VERIFY_ROLE}-read" "$verify_policy")
remember AUDIT_VERIFY_ROLE_ARN "$verify_role_arn"
aws configure set role_arn "$verify_role_arn" --profile "$VERIFY_PROFILE"
aws configure set source_profile "$ADMIN_PROFILE" --profile "$VERIFY_PROFILE"
aws configure set region "$REGION" --profile "$VERIFY_PROFILE"
step "프로필 $VERIFY_PROFILE 을 맞췄다(~/.aws/config)"

# ── 사진 버킷 — 자리만 ───────────────────────────────────────────────────
# 사진 저장(S3 — 같은 계정 · 다른 버킷 · 다른 권한)은 열람 방식이 정해진 뒤 여기에 걸음을 더한다. 버킷 이름과 권한
# JSON 은 그 결정의 문서가 「마법사가 쓸 값」으로 낸다 — 그 전에는 여기서 아무것도 만들지 않는다. 더할 때는 위
# `bucket_state` · `ensure_role` 을 그대로 쓰고(몇 번 돌려도 하나), TOTAL_STAGES 를 늘리고, 시험에 같은 갈래
# (처음 · 재실행 · 부분 실패 · 재사용)를 더한다.

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Vercel — Production 환경변수 셋"
# 반출을 켜기 전에 보존이 걸려 있어야 한다 — 기본 보존은 올리는 순간에만 붙어, 그 전에 올라간 객체는 영영 보존 없이 남는다
lock=$(lock_state "$bucket")
read -r mode days <<<"$lock"
[[ "$mode" == "GOVERNANCE" || "$mode" == "COMPLIANCE" ]] \
  || stop "버킷에 기본 보존이 없다 — 반출을 켜지 않는다(runbook 「반출」 3: Governance 를 건 뒤에 켠다)." \
    "다시 돌려 Stage 5 에서 y 로 답한다."
vercel_scope=(--project "$VERCEL_PROJECT" --scope "$VERCEL_TEAM")
existing=$(vercel env ls production "${vercel_scope[@]}" 2>/dev/null || true)
if grep -qE 'AUDIT_EXPORT_(ACCESS_KEY_ID|SECRET_ACCESS_KEY)' <<<"$existing"; then
  warn "Production 에 접근 키(AUDIT_EXPORT_ACCESS_KEY_ID · SECRET)가 있다 — 역할과 함께 있으면 오설정이다."
  note "Vercel 대시보드에서 그 둘을 지운 뒤 다시 돌린다(마법사는 변수를 지우지 않는다)."
  REMAINING+=("Stage 10 — 접근 키 두 변수를 대시보드에서 지운다")
fi
say "넣을 값: AUDIT_EXPORT_BUCKET · AUDIT_EXPORT_REGION($REGION) · AUDIT_EXPORT_ROLE_ARN — 셋 다 비밀이 아니다."
declare -A wanted=(
  [AUDIT_EXPORT_BUCKET]="$bucket"
  [AUDIT_EXPORT_REGION]="$REGION"
  [AUDIT_EXPORT_ROLE_ARN]="$export_role_arn"
)
# 상태 파일이 아니라 Production 의 실제 값과 견준다 — 대시보드에서 바뀐 값을 「그대로다」라 하지 않는다
pulled=yes
read_vercel_values || pulled=""
# 셋이 다 Production 에 이 마법사의 값으로 있는가 — Stage 12 · 13 의 문이다
vercel_ok=yes
for name in AUDIT_EXPORT_BUCKET AUDIT_EXPORT_REGION AUDIT_EXPORT_ROLE_ARN; do
  if grep -qw "$name" <<<"$existing"; then
    if [[ -z "$pulled" || -z "${remote[$name]:-}" ]]; then
      # 못 읽었다(Sensitive 면 값이 비어 온다) — 같다고 말하지 않는다
      warn "$name — Production 의 값을 못 읽어 이 마법사 값과 같은지 모른다"
      REMAINING+=("Stage 10 — Production 의 $name 값을 확인 못 함(대시보드에서 상태 파일의 같은 이름 줄과 견준다)")
      vercel_ok=""
      continue
    fi
    if [[ "${remote[$name]}" == "${wanted[$name]}" ]]; then
      step "$name — Production 값이 이 마법사 값과 같다"
      continue
    fi
    if ! confirm "$name 이 Production 에 이미 있다(다른 값). 이 마법사의 값으로 덮어쓸까?"; then
      REMAINING+=("Stage 10 — $name 를 덮어쓰지 않았다(값이 맞는지 대시보드에서 본다)")
      vercel_ok=""
      continue
    fi
    vercel env add "$name" production "${vercel_scope[@]}" --value "${wanted[$name]}" --no-sensitive --yes --force >/dev/null
  else
    vercel env add "$name" production "${vercel_scope[@]}" --value "${wanted[$name]}" --no-sensitive --yes >/dev/null
  fi
  remember REDEPLOY_PENDING "yes"
  step "$name 을 넣었다"
done

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Vercel — Production 다시 배포"
if [[ "$(state REDEPLOY_PENDING)" != "yes" ]]; then
  step "바뀐 변수가 없다 — 건너뛴다"
else
  say "환경변수는 다음 배포부터 든다. 최신 Production 을 그대로 Redeploy 한다(코드는 안 바뀐다)."
  open_url "https://vercel.com/${VERCEL_TEAM}/${VERCEL_PROJECT}/deployments"
  step "맨 위 Production(Current) 줄 → ⋯ → Redeploy → Redeploy"
  step "상태가 Ready 가 될 때까지 기다린다"
  if confirm "Redeploy 가 Ready 인가?"; then
    remember REDEPLOY_PENDING "no"
  else
    REMAINING+=("Stage 11 — Production Redeploy 뒤 Ready")
  fi
fi

# ── 12 ───────────────────────────────────────────────────────────────────
stage "첫 반출 · Governance 검증"
gov_set="$(state GOVERNANCE_SET_EPOCH)"
lock=$(lock_state "$bucket")
read -r mode days <<<"$lock"
# 검증이 본 설정 — 바뀌면 지난 검증은 지금 설정을 잰 것이 아니다. 보존은 따로 적는다(13 이 Governance → Compliance 로 바꾼다)
config_fp=$(fingerprint "$bucket" "$REGION" "$export_role_arn" "$verify_role_arn" "$export_trust" "$export_policy" \
  "$verify_trust" "$verify_policy" "$VERCEL_TEAM" "$VERCEL_PROJECT")
# 잴 수 있나 — 보존이 걸렸고 · OIDC 를 켰고 · Redeploy 가 끝났고 · Vercel 세 값이 이 마법사 값인 것을 읽어 확인했다
ready_to_measure() {
  [[ "$mode" != "None" && "$(state VERCEL_OIDC_READY)" == "yes" && "$(state REDEPLOY_PENDING)" != "yes" && -n "$vercel_ok" ]]
}
gov_ok="$(state GOVERNANCE_VERIFIED_EPOCH)"
if [[ -n "$gov_ok" ]] && { [[ "$(state GOVERNANCE_VERIFIED_FP)" != "$config_fp" ]] || ! ready_to_measure; }; then
  warn "지난 검증은 지금 설정과 다르다(또는 Redeploy · Vercel 값 확인이 남았다) — 무효로 하고 다시 잰다"
  remember GOVERNANCE_VERIFIED_EPOCH ""
  remember GOVERNANCE_VERIFIED_FP ""
  remember GOVERNANCE_VERIFIED_LOCK ""
  gov_ok=""
fi
# Governance 를 건 뒤 24시간이 지나서, 지금과 같은 설정 · 같은 보존에서 검증이 초록이었나 — 13 의 문이다
matured() {
  [[ -n "$gov_ok" && -n "$gov_set" ]] && (( gov_ok - gov_set >= DAY )) \
    && [[ "$(state GOVERNANCE_VERIFIED_LOCK)" == "$mode $days" ]]
}
long_compliance() { [[ "$mode" == "COMPLIANCE" && "$days" =~ ^[0-9]+$ ]] && (( days >= COMPLIANCE_DAYS )); }
if matured; then
  step "Governance 를 걸고 24시간 뒤에 지금 설정으로 검증했다 — 건너뛴다"
elif long_compliance && [[ -n "$gov_ok" ]]; then
  step "이미 Compliance ${days}일이고 지금 설정으로 검증했다 — 건너뛴다. 달마다의 검증은 runbook 「반출」 9"
elif ! ready_to_measure; then
  warn "Stage 5 · 6 · 10 · 11 이 남아 아직 잴 수 없다"
  REMAINING+=("Stage 12 — 5 · 6 · 10 · 11 을 끝낸 뒤 다시 돌린다")
else
  say "반출 크론을 지금 한 번 돌리고(매일 서울 03:37 전후에도 돈다), 셋을 본다 —"
  say "객체가 섰나 · 검증(audit:verify)이 초록인가 · 보존이 지우기를 막나."
  if confirm "반출 크론을 지금 한 번 돌릴까?"; then
    vercel crons run "$CRON_PATH" "${vercel_scope[@]}" >/dev/null \
      || warn "크론을 못 돌렸다 — 03:37 뒤의 정기 실행을 보고 다시 돌린다"
  fi
  step "반출 상태(개인을 가리키지 않는 보통 질의 — 접속기록에 목적과 해시가 남는다):"
  (cd "$REPO_ROOT" && npm run --silent db:remote -- --purpose "접속기록 반출 상태" \
    "select last_outcome, last_error_class, last_success_at, pending_rows from audit.export_status()") \
    || warn "상태를 못 읽었다 — 운영 DB 접속값(docs/ops/runbook/access.md)을 본다"
  if ! confirm "last_outcome 이 succeeded 인가?"; then
    REMAINING+=("Stage 12 — last_outcome 이 succeeded 가 아니다(runbook 「마법사가 멈췄을 때」의 분류 표)")
  else
    count=$(aws --profile "$VERIFY_PROFILE" --region "$REGION" s3api list-objects-v2 --bucket "$bucket" \
      --prefix "${EXPORT_PREFIX}/" --query KeyCount --output text)
    if [[ ! "$count" =~ ^[0-9]+$ || "$count" -lt 1 ]]; then
      warn "버킷에 ${EXPORT_PREFIX}/ 객체가 없다"
      REMAINING+=("Stage 12 — 객체가 없다")
    elif ! (cd "$REPO_ROOT" && AWS_PROFILE="$VERIFY_PROFILE" AUDIT_VERIFY_BUCKET="$bucket" \
        AUDIT_VERIFY_REGION="$REGION" npm run --silent audit:verify); then
      warn "검증이 붉다 — Compliance 로 가지 않는다"
      REMAINING+=("Stage 12 — audit:verify 가 붉다")
    else
      step "객체 ${count}개 · 검증 초록"
      # 지우기 시험은 감사 객체를 건드리지 않는다 — 보존이 끝난 옛 객체면 정말 지워진다. 시험 객체 하나를
      # 시험 자리에 새로 올려(올리는 순간 기본 보존이 붙는다) 그것을 버전째 지워 본다
      say "시험 객체 하나를 ${PROBE_PREFIX}/ 에 올리고 버전째 지워 본다 — 보존이 걸렸으면 AccessDenied 로 막힌다."
      if confirm "지우기 시험을 할까?"; then
        probe_body=$(mktemp)
        printf 'saju aws-wizard retention probe\n' >"$probe_body"
        probe_key="${PROBE_PREFIX}/$(now).txt"
        probe_version=$(awsa s3api put-object --bucket "$bucket" --key "$probe_key" --body "$probe_body" \
          --checksum-algorithm SHA256 --query VersionId --output text)
        rm -f "$probe_body"
        [[ -n "$probe_version" && "$probe_version" != "None" ]] \
          || stop "시험 객체의 버전을 못 받았다 — Versioning 을 본다."
        if delete_err=$(awsa s3api delete-object --bucket "$bucket" --key "$probe_key" \
            --version-id "$probe_version" 2>&1 >/dev/null); then
          stop "지워졌다 — 보존이 안 걸렸다. Compliance 로 가지 않는다." \
            "복구: docs/ops/runbook/security.md 「마법사가 멈췄을 때」의 「지워졌다 — 보존이 안 걸렸다」"
        fi
        grep -q 'AccessDenied' <<<"$delete_err" \
          || stop "지우기 시험이 보존이 아닌 까닭으로 실패했다 — 막혔는지 알 수 없다." "$delete_err"
        step "지우기가 막혔다(보존 ${mode} ${days}일)"
        remember GOVERNANCE_VERIFIED_EPOCH "$(now)"
        remember GOVERNANCE_VERIFIED_FP "$config_fp"
        remember GOVERNANCE_VERIFIED_LOCK "$mode $days"
        gov_ok="$(state GOVERNANCE_VERIFIED_EPOCH)"
        if ! matured; then
          REMAINING+=("Stage 12 — Governance 를 건 지 24시간이 안 됐다. 그 뒤 정기 반출이 한 번 돈 다음 다시 돌려 한 번 더 잰다")
        fi
      else
        REMAINING+=("Stage 12 — 지우기 시험")
      fi
    fi
  fi
fi

# ── 13 ───────────────────────────────────────────────────────────────────
stage "Compliance 400일로 옮기기 — 되돌릴 수 없다"
lock=$(lock_state "$bucket")
read -r mode days <<<"$lock"
if long_compliance; then
  step "이미 Compliance ${days}일이다 — 건너뛴다"
elif [[ "$mode" == "COMPLIANCE" ]]; then
  # 짧은 Compliance — 마법사는 늘리지 않는다. 되돌릴 수 없는 걸음이라 runbook 의 손 절차로(버킷 이름을 맞춰 친다)
  warn "기본 보존이 Compliance ${days}일 — ${COMPLIANCE_DAYS}일보다 짧다. 끝난 것으로 치지 않는다."
  note "늘리는 법: docs/ops/runbook/security.md 「마법사가 멈췄을 때」의 「Compliance N일 — 400일보다 짧다」"
  REMAINING+=("Stage 13 — 기본 보존이 Compliance ${days}일이다. runbook 의 절차로 ${COMPLIANCE_DAYS}일로 늘린 뒤 다시 돌린다")
elif [[ "$mode" != "GOVERNANCE" ]] || ! matured; then
  say "아직이다 — Governance 를 걸고 24시간 뒤에 Stage 12 가 초록이어야 옮긴다(runbook 「반출」 3 → 4)."
  REMAINING+=("Stage 13 — Compliance 400일 전환(Governance 24시간 뒤 Stage 12 가 초록인 다음)")
else
  warn "이 뒤에 올라오는 객체는 루트도 400일 동안 못 지우고, 보존을 줄일 수 없다."
  note "Compliance 는 그 뒤 올라오는 객체의 기본값이다 — Governance 시험 기간의 객체는 Governance 1일 그대로다(runbook 「반출」 4)."
  printf '  %s? 옮기려면 버킷 이름을 그대로 친다:%s ' "$YELLOW" "$RESET"
  typed=""
  read -r typed || true
  if [[ "$typed" == "$bucket" ]]; then
    awsa s3api put-object-lock-configuration --bucket "$bucket" --object-lock-configuration \
      '{"ObjectLockEnabled":"Enabled","Rule":{"DefaultRetention":{"Mode":"COMPLIANCE","Days":'"$COMPLIANCE_DAYS"'}}}' >/dev/null
    lock=$(lock_state "$bucket")
    read -r mode days <<<"$lock"
    [[ "$mode" == "COMPLIANCE" && "$days" == "$COMPLIANCE_DAYS" ]] || stop "다시 읽은 기본 보존이 $mode $days 이다."
    remember COMPLIANCE_SET_AT "$(today)"
    step "Compliance 400일을 걸었다"
  else
    REMAINING+=("Stage 13 — 이름이 달라 옮기지 않았다")
  fi
fi

trap - ERR
finish
# 「끝」은 다시 읽은 기본 보존이 Compliance 400일 이상이고 남은 것이 없을 때만 말한다
if (( ${#REMAINING[@]} )) || ! long_compliance; then
  warn "남은 것 — 끝내고 다시 돌린다(된 걸음은 건너뛴다):"
  for r in "${REMAINING[@]}"; do note "  - $r"; done
  long_compliance || (( ${#REMAINING[@]} )) || note "  - 기본 보존이 아직 Compliance ${COMPLIANCE_DAYS}일이 아니다(지금 $mode $days)"
else
  printf '  %s반출이 Compliance %s일로 돈다.%s\n' "$GREEN" "$days" "$RESET"
  note "Compliance 는 전환 뒤 올라오는 객체의 기본값이다 — Governance 시험 기간의 객체는 Governance 1일 그대로다(하루 뒤 풀린다)."
fi
note "값은 $ENV_FILE 에 있다 — 문서 · 채팅 · 커밋에 옮기지 않는다. #304 의 7 에는 「끝」과 날짜만 적는다."
printf '\n'
